CREATE TABLE IF NOT EXISTS gis_admin_identity_crosswalk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_dataset_id uuid NOT NULL, primary_feature_code text NOT NULL, primary_name text NOT NULL, primary_parent_code text, comparison_dataset_id uuid NOT NULL, comparison_feature_code text NOT NULL, comparison_name text NOT NULL, comparison_parent_code text, match_method text NOT NULL, name_similarity numeric, parent_match boolean NOT NULL DEFAULT false, spatial_evidence numeric, confidence numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Candidate', review_required boolean NOT NULL DEFAULT true, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_admin_crosswalk_primary ON gis_admin_identity_crosswalk(primary_dataset_id,primary_feature_code);
CREATE INDEX IF NOT EXISTS idx_admin_crosswalk_status ON gis_admin_identity_crosswalk(status,confidence);
CREATE TABLE IF NOT EXISTS gis_identity_resolution_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_reference text NOT NULL UNIQUE, primary_dataset_id uuid NOT NULL, comparison_dataset_id uuid NOT NULL, primary_feature_count integer NOT NULL, comparison_feature_count integer NOT NULL, high_confidence_count integer NOT NULL DEFAULT 0, review_count integer NOT NULL DEFAULT 0, unresolved_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'ReviewRequired', created_at timestamptz NOT NULL DEFAULT now());